#!/bin/zsh
# Saison 2, chapitre 16 : grande salle, variante avec des élèves assis aux tables du fond (la réplique d'ouverture les cite).
cd "$(dirname "$0")/.." || exit 1
ST="hand-painted 2000s 2D point-and-click adventure game background, painterly detailed backgrounds like classic adventure games, bold dark outlines, saturated colors, humorous storybook fantasy, wide establishing shot at eye level, no logo, no coat of arms, no watermark, no frame, no text, no letters, no writing"
H="A huge medieval castle great hall at night seen from its center aisle: four very long wooden dining tables with benches run from the middle ground to the back on both sides, set with golden plates and goblets; many small teenage students in long black school robes sit at the tables in the middle and far background, turned toward the center aisle, watching; at the back, a raised wooden high table for the teachers in front of a tall gothic stained-glass window with plain colored diamond panes; tall stone walls with gothic arches and simple colored banners without any emblem; the ceiling is open onto a deep blue starry night sky with a few soft clouds, as if enchanted; NO candles anywhere, no candlesticks, no torches, the hall is lit by a warm golden glow; the polished wooden floor of the wide empty center aisle fills the whole lower third of the picture, flat and walkable from left to right, nobody in the foreground."
for sd in 4 5 6; do out="work/s2play/d_hall_$sd.png"; [ -f "$out" ] || flux-image "$H $ST" -i crossover/img/r_potter.jpg -s 1280x720 --seed $sd -o "$out"; done
echo fini
